function OverseaStoreDialog:Awake()
    local behaviourAction = CfUtils.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = Bind(self, self.Update)
        self._behaviourAction = behaviourAction
    end
end

function OverseaStoreDialog:OnFocus(focus)
    if focus then
        -- 设置相机状态
        CfUtils.SetTopRightProjection(0)
        CfUtils.SetUICameraProjection(true)
        
        local node = self:GetStoreNodeByStoreType(self:GetSelectedStoreType())
        if node and node.scr and node.scr.RefreshCurrencyBar then
            node.scr:RefreshCurrencyBar(self:GetSelectedStoreType())
        end

        if self:GetFindId() and self._showFindView then
            CfUtils.RefreshTopGoods({Constants.Currency.FreeDiamondId})
        end
    end
end

function OverseaStoreDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CriWareUtils.PlayMusicById("bgm_shop")
        self:InitHandler()
        self:InitData()
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
    end))
    return coWait
end

function OverseaStoreDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        -- 关闭定时器
        OverseaStoreMgr:StopTimer()
        
        CfUtils.EventsUndecorated(self._events)

        if self._behaviourAction then
            self._behaviourAction.UpdateAction = nil
            self._behaviourAction = nil
        end
        
        -- 退出商城时清除new标记
        OverseaStoreMgr:ClearNewStore()
        self:UpdateRedPoint()

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function OverseaStoreDialog:Update()
    if Utils.TouchCount() > 0 and (not self.__closing) then
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            local camera = UIModule.RootCanvas.canvas.worldCamera
            local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self.RetrievalTips, position, camera)
            local isActive = KTool.IsActive(self.RetrievalTips.gameObject)
            if isActive and not isInRect then
                CfUtils.SetActive(self.RetrievalTips, false)
            end
        end
    end
end
