---初始化搜索页签数据
function OverseaStoreDialog:InitFindData()
    local goodsId = self:GetFindId()
    if not goodsId then return end

    local findData = {}
    local findId = self:GetFindId()
    local tabData = self:GetTabData()
    local subData = self:GetSubTabData()
    for i, v in ipairs(tabData) do
        if subData[i] then
            -- 存在子页签
            for _, sub in ipairs(subData[i]) do
                self:FindItem(sub.type, findId, findData)
            end
        else
            self:FindItem(v.type, findId, findData)
        end
    end
    self:SetFindData(findData)
end

---初始化主页签数据
function OverseaStoreDialog:InitMainTabData()
    local tabData = {}
    local ThirdDownloadManager = import("Game.Entry.ThirdDownloadManager"):GetInstance()
    local isDownloadAndPlaying = ThirdDownloadManager:IsNotDwonloadingEnd()
    for _, storeType in ipairs(MainTabGroup) do
        local data = {}
        local conf = OverseaStoreConstants.StorePanelConfigs[storeType]
        local isOpen =  CfUtils.IsOpneByFunctionId(conf.functionId)
        if storeType == OverseaStoreConstants.StoreType.TimeLimit then
            -- 特殊处理，限时活动礼包为空时隐藏页签
            local storeData = OverseaStoreMgr:GetTimeLimitActivityData()
            if not next(storeData) then
                isOpen = false
            end
        elseif storeType == OverseaStoreConstants.StoreType.Gift or storeType == OverseaStoreConstants.StoreType.Skin then
            -- 子页签存在解锁条件，如果子页签都未解锁则隐藏页签
            local sub = OverseaStoreConstants.StorePanelConfigs[storeType].sub
            if sub then
                local hasProduct = false
                for _, v in ipairs(sub) do
                    local subConf = OverseaStoreConstants.StorePanelConfigs[v.type]
                    if not subConf.functionId or CfUtils.IsOpneByFunctionId(subConf.functionId) then
                        local storeData = OverseaStoreMgr:GetStoreDataByType(v.type)
                        if next(storeData) then
                            hasProduct = true
                            break
                        end
                    end
                end
                if not hasProduct then
                    isOpen = false
                end 
            end
        elseif storeType == OverseaStoreConstants.StoreType.OptionalGift or storeType == OverseaStoreConstants.StoreType.RenovateShop then
            local storeData = OverseaStoreMgr:GetStoreDataByType(storeType)
            if not isNull(storeData) and next(storeData) and table.count(storeData.products) > 0 then
                isOpen = true
            else
                isOpen = false
            end
        end
        
        if storeType == OverseaStoreConstants.StoreType.PrimaryCurrency then
            ---@type ServerDifferenceMgr
            local serverDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
            isOpen = serverDifferenceMgr:IsSecondaryCurrencyEnable() and CfUtils.IsOpneByFunctionId(conf.functionId)
        end
        if isOpen  and (not (storeType == OverseaStoreConstants.StoreType.Skin and isDownloadAndPlaying)) then
            data = {
                name        = self:GetStoreName(storeType),
                bgPath      = conf.iconPath,
                type        = storeType,
                func        = Bind(self, self.StoreTabOnClickHandler),
                redPointFun = Bind(self, self.StoreTabOnRedPointHandler),
                newSymbolFun = Bind(self, self.StoreTabOnNewSymbolHandler),
                countDownData    = self:GetCountDown(storeType)
            }
            table.insert(tabData, data)
        end
    end

    self:SetTabData(tabData)
    
    self:CheckTabUnlock()
end

function OverseaStoreDialog:GetCountDown(type)
    if type == OverseaStoreConstants.StoreType.RenovateShop then
        local storeData = OverseaStoreMgr:GetStoreDataByType(OverseaStoreConstants.StoreType.RenovateShop)
        return {isCountDown = true ,remainTime =  storeData.remainTime }
    elseif type == OverseaStoreConstants.StoreType.OptionalGift then
        local storeData = OverseaStoreMgr:GetStoreDataByType(OverseaStoreConstants.StoreType.OptionalGift)
        return {isCountDown = true ,remainTime =  storeData.nextRefreshLeftSeconds }
    elseif type == OverseaStoreConstants.StoreType.LimitedTimeSkin then
        local storeData = OverseaStoreMgr:GetStoreDataByType(type)
        return {isCountDown = true ,remainTime =  storeData.nextRefreshLeftSeconds }
    elseif type == OverseaStoreConstants.StoreType.Skin then
        local storeData = OverseaStoreMgr:GetStoreDataByType(OverseaStoreConstants.StoreType.LimitedTimeSkin)
        if storeData.nextRefreshLeftSeconds and checkInt(storeData.nextRefreshLeftSeconds) > 0 then
            return {isCountDown = true ,remainTime = storeData.nextRefreshLeftSeconds }
        end
    end
    return {isCountDown = false ,remainTime = 0 }
end

---初始化子页签数据
function OverseaStoreDialog:InitSubTabData()
    self._subTabData = {}
    local tabData = self:GetTabData()
    for _, tab in ipairs(tabData) do
        local config = OverseaStoreConstants.StorePanelConfigs[tab.type] or {}
        if tab.type == OverseaStoreConstants.StoreType.RenovateShop then
            local subData = {}
            local storeData = OverseaStoreMgr:GetStoreDataByType(tab.type)
            if not isNull(storeData) and table.count(checkTable(storeData.products)) > 1 then
                for i, v in pairs(storeData.products) do
                    local data = {
                        name        = self:GetSuitName(v.avatarSuitId),
                        func        = Bind(self, self.StoreTabOnClickHandler),
                        type        = OverseaStoreConstants.StoreType.RenovateShop,
                        redPointFun = Bind(self, self.StoreTabOnRedPointHandler),
                        newSymbolFun = Bind(self, self.StoreTabOnNewSymbolHandler)
                    }
                    table.insert(subData, data)
                end
                self:SetSubTabDataByStoreType(tab.type, subData)
            end
        else
            if config.sub then
                local subData = {}
                for _, subConf in ipairs(config.sub) do
                    local conf = OverseaStoreConstants.StorePanelConfigs[subConf.type]
                    local isOpen =  CfUtils.IsOpneByFunctionId(conf.functionId)
                    local storeData = OverseaStoreMgr:GetStoreDataByType(subConf.type)
                    if not next(checkTable(storeData.products)) then
                        isOpen = false
                    end
                    if isOpen then
                        local data = {
                            name        = self:GetStoreName(subConf.type),
                            func        = Bind(self, self.StoreTabOnClickHandler),
                            type        = subConf.type,
                            redPointFun = Bind(self, self.StoreTabOnRedPointHandler),
                            newSymbolFun = Bind(self, self.StoreTabOnNewSymbolHandler)
                        }
                        table.insert(subData, data)
                    end
                end
                self:SetSubTabDataByStoreType(tab.type, subData)
            end
        end
    end
end

function OverseaStoreDialog:GetSuitName(refId)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting4113, "MaidCoffeeRenovateSuitVo", refId)
    if not isNull(vo) then
        return vo.name
    end
    return ""
end

---初始化选中的页签
function OverseaStoreDialog:InitSelectedTab()
    if self:GetFindId() then
        self:SetSelectedTab(FindViewTabIndex)
        return
    end
    
    if not self._parameter.storeType then return end

    local idx, subIdx = self:GetTabIndexByStoreType(self._parameter.storeType)
    if not idx then return end

    self:SetSelectedTab(idx)
    self:SetSelectedSubTab(subIdx)
    --self._parameter.storeType = nil
end
