--region handler
---页签点击回调
---@param data table
--- * type OverseaStoreConstants.StoreType 类型
--- * __ind integer 索引
--- * isChild integer 是否为子页签
function OverseaStoreDialog:StoreTabOnClickHandler(data)
    local parentType = nil
    local curType = self:GetSelectedStoreType()
    ---@type OverseaStoreConstants.StorePanelConfigs
    local config = OverseaStoreConstants.StorePanelConfigs[curType]
    if config and config.parent then
        parentType = config.parent
    end

    if self:GetForceRefresh() then
        self:SetForceRefresh(false)
    else
        if curType == data.type then return end

        local curNode = self:GetStoreNodeByStoreType(parentType or curType)
        if curNode then
            -- 隐藏当前node
            self:SetCanvasEnabled(curNode, false)
        end
    end

    --if data.isChild then
    --    self:SetSelectedSubTab(data.__ind)
    --    self:ShowStoreNode(data.type)
    --else
    --    self:SetSelectedTab(data.__ind)
    --    -- 判断页签是否有子页签
    --    if not self:CheckSubTabByStoreType(data.type) then
    --        self:SetSelectedSubTab(0)
    --        self:ShowStoreNode(data.type)
    --    end
    --end

    self:SetSelectedTab(data.__ind)
    -- 判断页签是否有子页签
    local mainConf = OverseaStoreConstants.StorePanelConfigs[data.type]
    if mainConf.sub then
        -- 存在子页签
        if self._parameter.storeType == nil then
            self:SetSelectedSubTab(1)
        else
            if self:GetSelectedSubTab() == 0 then
                self:SetSelectedSubTab(1)
            end
            self._parameter.storeType = nil
        end
        self:RefreshTopTab()
    else
        if data.type == OverseaStoreConstants.StoreType.RenovateShop then
            local storeData = OverseaStoreMgr:GetStoreDataByType(data.type)
            if not isNull(storeData) and table.count(checkTable(storeData.products)) > 1 then
                -- 存在子页签
                if self._parameter.storeType == nil then
                    self:SetSelectedSubTab(1)
                else
                    if self:GetSelectedSubTab() == 0 then
                        self:SetSelectedSubTab(1)
                    end
                    self._parameter.storeType = nil
                end
                self:RefreshTopTab()
            else
                CfUtils.SetActive(self.CommonTabToggleUp, false)
                self:SetSelectedSubTab(0)
                self:ShowStoreNode(data.type)
            end
        else
            CfUtils.SetActive(self.CommonTabToggleUp, false)
            self:SetSelectedSubTab(0)
            self:ShowStoreNode(data.type)
        end
        self._parameter.storeType = nil
    end
    
    self:ClickRecord(data.type)

    if self:GetFindId() and self._showFindView then
        self._showFindView = false  
        self:SetCanvasEnabled(self.UIContainer, true)
        CfUtils.SetActive(self.RetrievalView, false)
    end
end

---顶部页签点击回调
function OverseaStoreDialog:StoreTopTabOnClickHandler(index)
    local subData = self:GetSubTabData()[self:GetSelectedTab()]
    if not subData then return end

    if index ~= self:GetSelectedSubTab() then
        local curNode = self:GetStoreNodeByStoreType(subData[self:GetSelectedSubTab()].type)
        if curNode then
            -- 隐藏当前node
            self:SetCanvasEnabled(curNode, false)
        end
        self:SetSelectedSubTab(index)
    end
    self:ClickRecord(subData[index].type)
    self:ShowStoreNode(subData[index].type)
    OverseaStoreMgr:RecordSelectedStore(subData[index].type)
end

---搜索页签点击回调处理
function OverseaStoreDialog:FindTabOnClickHandler()
    if self._showFindView then return end
    
    local curNode = self:GetStoreNodeByStoreType(self:GetSelectedStoreType())
    if curNode then
        -- 隐藏当前node
        self:SetCanvasEnabled(curNode, false)
    end

    self._showFindView = true
    self:SetSelectedTab(FindViewTabIndex)
    self:RefreshStoreList()
    self:SetCanvasEnabled(self.UIContainer, false)
    CfUtils.SetActive(self.RetrievalView, true)
    self:RefreshFindView()
    CfUtils.RefreshTopGoods({})
end

---页签红点处理
function OverseaStoreDialog:StoreTabOnRedPointHandler(data)
    local redPoint = 0
    local config = OverseaStoreConstants.StorePanelConfigs[data.type]

    if config and config.redPoint then
        redPoint = checkInt(redPointCom:GetNodeNum(config.redPoint))
    end
    return redPoint > 0
end

