---商城home回调处理
function OverseaStoreDialog:StoreHomeResponseHandler(request, response)
    self.leftTabExpandEnv_ = CfUtils.GetLuaScr(self.CommonTabToggleLeftExpand, OverseaStoreConstants.ScrPath.CommonTabToggleLeftExpand)
    OverseaStoreMgr:InitStoreHomeData(response.data)
    if not self._parameter.storeType and self:GetSelectedStoreType() then
        self._parameter.storeType = self:GetSelectedStoreType()
    end
    -- 刷新可能会导致页面消失，先隐藏
    local curNode = self:GetStoreNodeByStoreType(self:GetSelectedStoreType())
    if curNode then
        -- 隐藏当前node
        self:SetCanvasEnabled(curNode, false)
    end
    self:UpdateRedPoint()
    self:InitStoreTabData()
    self:RefreshUI()
end

