---页签切换逻辑
---@param storeType OverseaStoreConstants.StoreType
---@param parameters table | nil 额外参数
function OverseaStoreDialog:SwitchEventHandler(storeType, parameters)
    local idx, subIdx = self:GetTabIndexByStoreType(storeType)
    if not idx then return end

    local curNode = self:GetStoreNodeByStoreType(self:GetSelectedStoreType())
    if curNode then
        -- 隐藏当前node
        self:SetCanvasEnabled(curNode, false)
    end

    self:SetSelectedTab(idx)
    self:SetSelectedSubTab(subIdx)
    self:RefreshUI()
end

