---刷新UI
function OverseaStoreDialog:RefreshUI()
    CfUtils.SetActive(self.RetrievalTab, self:GetFindId() and true or false)
    self:SetForceRefresh(true)
    self:RefreshStoreList()

    if self:GetFindId() and self._showFindView then
        self:SetCanvasEnabled(self.UIContainer, false)
        CfUtils.SetActive(self.RetrievalView, true)
        self:RefreshFindView()
        return
    end
    self:SetCanvasEnabled(self.UIContainer, true)
    CfUtils.SetActive(self.RetrievalView, false)
end

---刷新查找页面
function OverseaStoreDialog:RefreshFindView()
    local data = self:GetFindData()
    if not self.RetrievalScrollView.mLoopListView.IsListViewInit then
        self.RetrievalScrollView:InitListView(#data, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.RetrievalScrollView, #data)
    end

    local findId = self:GetFindId()
    local goodsVo = GoodsConfMgr:GetGoodsVoById(findId)
    local desc = ''
    if #data == 0 then
        desc = localize("未找到包含<color=#30ffee>【_name_】</color>的商品", {_name_ = goodsVo.name})
    else
        desc = localize("已为您找到包含<color=#30ffee>【_name_】</color>的商品:", {_name_ = goodsVo.name})
    end
    CfUtils.FillText(self.RetrievalTextDesc , desc)
    CfUtils.FillText(self.RetrievalTipsTextDesc, localize("自动检索范围：商城中已解锁的商店，除【每日特惠】【免费商品】之外。"))
    CfUtils.SetActive(self.CommonTabToggleUp, false)
end

---刷新商店列表
function OverseaStoreDialog:RefreshStoreList()
    self.leftTabExpandEnv_ = CfUtils.GetLuaScr(self.CommonTabToggleLeftExpand, OverseaStoreConstants.ScrPath.CommonTabToggleLeftExpand)
    if isNull(self.leftTabExpandEnv_) then return end

    self.leftTabExpandEnv_:Refresh(
            self:GetTabData(),
            nil,
            self:GetSelectedTab(),
            self:GetSelectedSubTab()
    )
end

---刷新顶部页签
function OverseaStoreDialog:RefreshTopTab()
    local scr = CfUtils.GetLuaScr(self.CommonTabToggleUp.gameObject, "Game.Behaviours.CommonTabToggleUp")
    if isNull(scr) then return end
    
    local subData = self:GetSubTabData()[self:GetSelectedTab()]
    local toggleData = {}
    for _, v in ipairs(subData) do
        local tmp = {
            text = v.name,
            redPointStrNode = OverseaStoreConstants.StorePanelConfigs[v.type].redPoint,
            func = Bind(self, self.StoreTopTabOnClickHandler),
            isNew = OverseaStoreMgr:IsNewStore(v.type),
            countDownData = self:GetCountDown(v.type),
            showBlackBg = true
        }
        table.insert(toggleData, tmp)
    end
    scr:FillToggles(toggleData)
    scr:SetSelectState(self:GetSelectedSubTab(), true)
    CfUtils.SetActive(self.CommonTabToggleUp, #toggleData > 1)
end

---显示一个商店页面
---@param storeType OverseaStoreConstants.StoreType
function OverseaStoreDialog:ShowStoreNode(storeType)
    if not storeType then return end

    ---@type OverseaStoreConstants.StorePanelConfigs
    local config = OverseaStoreConstants.StorePanelConfigs[storeType]
    CfUtils.SetActive(self.ImgBgLeft, config.showImgBg == true)
    CfUtils.SetActive(self.OverseaMallSkinStaticNode, false)
    self._tempVideoPath = nil
    if isNotNull(self.VideoNodeMovie.player) then
        self.VideoNodeMovie:Stop()
    end
    CfUtils.SetActive(self.OverseaMallSkinVideoNode, false)
    
    
    local nodes = self:GetStoreNodes()
    if nodes[storeType] then
        self:RefreshStoreNode(storeType)
    else
        self:CreateStoreNode(storeType)
    end
end

---刷新商店页面
---@param storeType OverseaStoreConstants.StoreType
function OverseaStoreDialog:RefreshStoreNode(storeType)
    local node = self:GetStoreNodeByStoreType(storeType)
    if not node then return end
    
    self:SetCanvasEnabled(node, true)
    if not isNull(node.scr) then

        if node.scr.SetDelegate then
            node.scr:SetDelegate(self)
        end
        if node.scr.Refresh then
            node.scr:Refresh(storeType)
        end
        if node.scr.RefreshCurrencyBar then
            node.scr:RefreshCurrencyBar(storeType)
        else
            CfUtils.RefreshTopGoods({Constants.Currency.FreeDiamondId})
        end
    end
    
    self:SaveUIState()
end

---创建一个商店页面
---@param storeType OverseaStoreConstants.StoreType
function OverseaStoreDialog:CreateStoreNode(storeType)
    CfUtils.StartCoroutineWithBlocker(function()
        xTry(function()
            local config = OverseaStoreConstants.StorePanelConfigs[storeType]
            if not config or not config.prefabId then return end
            local go = GameUtils.LoadBundleAsyncById(config.prefabId, self.UIContainer.gameObject, false)
            local scr = CfUtils.GetLuaScr(go, config.scrPath)
            local node = {
                go = go,
                scr = scr,
            }
            self:SetStoreNodeByStoreType(storeType, node)
            self:RefreshStoreNode(storeType)
        end)
    end)
end

---检查页签是否存在子页签
---@param storeType OverseaStoreConstants.StoreType
---@return boolean
function OverseaStoreDialog:CheckSubTabByStoreType(storeType)
    local index = self:GetTabIndexByStoreType(storeType)
    if not index then return end

    local subTabData = self:GetSubTabData()
    return subTabData[index] and true or false
end

---保存页签状态
function OverseaStoreDialog:SaveUIState()
    if not self.controller.Argument.parameters then
        local arguments = CS.Engine.UI.UIArgument()
        arguments = {
            id = self.controller.Argument.id,
            path = self.controller.Argument.path,
            status = self.controller.Argument.status,
            isBackable = self.controller.Argument.isBackable,
            extra = self.controller.Argument.extra,
            hasExcluded = self.controller.Argument.hasExcluded,
            parameters = {}
        }
        self.controller.Argument = arguments
    end
    
    local parameters = self.controller.Argument.parameters or {}
    parameters.storeType = self:GetSelectedStoreType()
    self.controller.Argument.parameters = parameters
end

---更新页签红点
function OverseaStoreDialog:UpdateRedPoint()
    self:UpdateCommonStoreRedPoint()
    -- 限时特惠红点
    self:UpdateTimeLimitDailyRedPoint()
end

---更新通用商城红点 
function OverseaStoreDialog:UpdateCommonStoreRedPoint()
    for type, conf in pairs(OverseaStoreConstants.StorePanelConfigs) do
        if type ~= OverseaStoreConstants.StoreType.RenovateShop then
            if conf.redPoint and conf.dataKey then
                local isOpen = true
                if conf.functionId then
                    isOpen = CfUtils.IsOpneByFunctionId(conf.functionId)
                end
                local isUnlock = true
                if conf.unlockId then
                    isUnlock = GameUtils.IsUnlockedBySystemTogId(conf.unlockId)
                end

                if isOpen and isUnlock then
                    local redPoint = 0
                    local data = OverseaStoreMgr:GetStoreDataByType(type)
                    for _, product in ipairs(checkTable(data.products)) do
                        if not OverseaStoreUtils.ProductIsSoldOut(product) and OverseaStoreUtils.ProductIsFree(product) and not OverseaStoreMgr:IsNewStore(type) then
                            redPoint = 1
                        end
                    end
                    GameUtils.SetRedPointNum(conf.redPoint, redPoint)
                end
            end
        end
    end
    GameUtils.SetRedPointNum(Constants.RedPointConst.OverseaStoreNew, OverseaStoreMgr:CheckNewStore() and 1 or 0)
end

---更新限时特惠红点
function OverseaStoreDialog:UpdateTimeLimitDailyRedPoint()
    local redPoint = 0
    local dailyOfferData = OverseaStoreMgr:GetTimeLimitDailyData()
    for i = 1 , #dailyOfferData -1 do 
        local v = dailyOfferData[i]
        if checkInt(v.isDraw) == 1 then
            redPoint = 1
            break
        end
    end    
    GameUtils.SetRedPointNum(Constants.RedPointConst.OverseaStoreTimeLimitDaily, redPoint)
    GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.OverseaStoreTimeLimitDaily )
end

---检查页签是否解锁, 如果子全未解锁移除主页签
function OverseaStoreDialog:CheckTabUnlock()
    local tabData = self:GetTabData()
    for i = #tabData, 1, -1 do
        local config = OverseaStoreConstants.StorePanelConfigs[tabData[i].type] or {}
        if config.sub then
            -- 存在子页签
            local isUnlock = false
            for _, subConf in ipairs(config.sub) do
                if self:CheckSubTabUnlock(subConf.type) then
                    isUnlock = true
                    break
                end
            end
            if not isUnlock then
                table.remove(tabData, i)
            end
        elseif config.unlockId then
            -- 不存在子页签, 主页签存在解锁条件
            if not GameUtils.IsUnlockedBySystemTogId(config.unlockId) then
                table.remove(tabData, i)
            end
        end
    end
end

---判断子页签是否解锁
---@param storeType OverseaStoreConstants.StoreType 类型
function OverseaStoreDialog:CheckSubTabUnlock(storeType)
    local config = OverseaStoreConstants.StorePanelConfigs[storeType]
    if config.unlockId then
        return GameUtils.IsUnlockedBySystemTogId(config.unlockId)
    else
        return true
    end
end

