---根据商城类型查找指定商品
---@param storeType OverseaStoreConstants.StoreType
---@param goodsId integer 道具id
---@param itemList table 商品列表
function OverseaStoreDialog:FindItem(storeType, goodsId, itemList)
    local config = OverseaStoreConstants.StorePanelConfigs
    if checkTable(config[storeType]).dataKey then
        local storeData = OverseaStoreMgr:GetStoreDataByType(storeType)
        for _, itemData in ipairs(checkTable(storeData.products)) do
            if checkInt(itemData.icon) == checkInt(goodsId) then
                if checkInt(itemData.isFree) ~= 1 then
                    local data = self:ConvertFindItemData(storeType, itemData, storeData)
                    table.insert(itemList, data)
                end
            else
                if itemData.rewards then
                    for _, rewardData in ipairs(checkTable(itemData.rewards)) do
                        if rewardData.goodsId == goodsId then
                            if checkInt(itemData.isFree) ~= 1 then
                                local data = self:ConvertFindItemData(storeType, itemData, storeData)
                                table.insert(itemList, data)
                                break
                            end
                        end
                    end
                end
            end
        end
    end
end

---转换查找道具数据
---@param storeType OverseaStoreConstants.StoreType
---@param itemData table 商店道具数据
---@param storeData table 商店数据
function OverseaStoreDialog:ConvertFindItemData(storeType, itemData, storeData)
    local data = clone(itemData)
    if checkInt(storeData.nextRefreshLeftSeconds) > 0 then
        data.nextRefreshLeftSeconds = storeData.nextRefreshLeftSeconds
    end
    data.storeType = storeType

    --if storeType == OverseaStoreConstants.StoreType.TimeLimit then
    --end
    return data
end

---播放视频
function OverseaStoreDialog:PlayVideo(videoPath)
    if self.VideoNodeMovie.loop == false then
        self.VideoNodeMovie.loop = true
    end 
    
    -- 如果播放器 还未变到 停止状态：则先记录要播放的视频名，让播放器停止掉，等待播放器状态变为停止视，再播放才能正常。
    if isNotNull(self.VideoNodeMovie.player)   then
        if  self.VideoNodeMovie.player.status ~= CS.CriWare.CriMana.Player.Status.Stop then
            self._tempVideoPath = videoPath
            self.VideoNodeMovie:Stop()  -- 当前帧不会立刻变为 stop 状态 
        else
            local poolVideoPath = GameUtils.GetManaPath(videoPath)
            self.VideoNodeMovie.player:SetFile(nil, poolVideoPath)
            self.VideoNodeMovie:Play()  -- 当前帧不会立刻变为 play 状态     
        end
    end
end
