---通过商店类型获取页签索引
---@return integer, integer 主页签索引，子页签索引
function OverseaStoreDialog:GetTabIndexByStoreType(storeType)
    local tabData = self:GetTabData()
    local subTabData = self:GetSubTabData()
    for idx, conf in ipairs(tabData) do
        if subTabData[idx] then
            for subIdx, subConf in ipairs(subTabData[idx]) do
                if subConf.type == storeType then
                    return idx, subIdx
                end
            end
        else
            if conf.type == storeType then
                return idx
            end
        end
    end
end

---获取选中的商店类型
---@return OverseaStoreConstants.StoreType
function OverseaStoreDialog:GetSelectedStoreType()
    local tabIdx = self:GetSelectedTab()
    local subTabData = self:GetSubTabData()
    if subTabData[tabIdx] then
        local subTabIdx = self:GetSelectedSubTab()
        local subDataList = checkTable(subTabData[tabIdx])
        local subData = checkTable(subDataList[subTabIdx])
        return subData.type
    end

    local tabData = self:GetTabData()
    return checkTable(tabData[tabIdx]).type
end

